#!/usr/bin/env bash
set -euo pipefail

rm -rf dist
mkdir -p dist
cp index.html styles.css app.js purchase-engine.js catalog-controls.js cloudflare-sync.js ui-translation-extra.js sw.js master.json manifest.webmanifest hero-food.jpg hero-bar.jpg LRX-LOGO-PLANTILLAS.png LRX-LOGO-IMPRESION-TRANSPARENTE.png dist/
mkdir -p dist/assets
cp -R assets/utensils dist/assets/

python3 - <<'PY'
from pathlib import Path
p = Path("dist/app.js")
s = p.read_text()
needle = "function updateLanguageChip(){"
bridge = "const __lrxBaseApplyEnglishUI=applyEnglishUI;const __lrxRawText=new WeakMap();const __lrxRenderedText=new WeakMap();const __lrxRawAttrs=new WeakMap();const __lrxRenderedAttrs=new WeakMap();let __lrxTranslateLookup=new Map();let __lrxPhraseRegex=null;const __lrxBuildTranslationIndex=()=>{__lrxTranslateLookup=new Map(Object.entries(UI_EN).map(([k,v])=>[k.toLocaleLowerCase(),v]));const keys=Object.keys(UI_EN).filter(k=>k.length>=4&&/^[A-Za-zÀ-ÖØ-öø-ÿ0-9 ]+$/.test(k)).sort((a,b)=>b.length-a.length);__lrxPhraseRegex=keys.length?new RegExp('(^|[^A-Za-zÀ-ÖØ-öø-ÿ0-9])('+keys.join('|')+')(?=$|[^A-Za-zÀ-ÖØ-öø-ÿ0-9])','gi'):null};__lrxBuildTranslationIndex();const __lrxTranslateValue=value=>{if(typeof value!=='string'||state.settings?.language!=='en')return value;let out=UI_EN[value]??__lrxTranslateLookup.get(value.toLocaleLowerCase())??value;const monthNames={Enero:'January',Febrero:'February',Marzo:'March',Abril:'April',Mayo:'May',Junio:'June',Julio:'July',Agosto:'August',Septiembre:'September',Octubre:'October',Noviembre:'November',Diciembre:'December'};for(const [es,en] of Object.entries(monthNames))out=out.replace(new RegExp('(^|[^A-Za-zÀ-ÖØ-öø-ÿ])'+es+'(?=$|[^A-Za-zÀ-ÖØ-öø-ÿ])','g'),(m,p)=>p+en);out=out.replace(/\\\\bMostrando\\\\b/g,'Showing').replace(/\\\\bPágina\\\\b/g,'Page').replace(/\\\\bde (\\\\d+) records/g,'of $1 records').replace(/\\\\bde (\\\\d+) resultados/g,'of $1 results').replace(/\\\\bregistros\\\\b/g,'records').replace(/\\\\bfichas\\\\b/g,'records').replace(/\\\\bmovimientos\\\\b/g,'transactions').replace(/\\\\bcompras\\\\b/g,'purchases').replace(/\\\\bgastos\\\\b/g,'expenses').replace(/\\\\bingresos\\\\b/g,'income').replace(/\\\\bórdenes\\\\b/gi,'orders').replace(/\\\\bord enes\\\\b/gi,'orders');return out};applyEnglishUI=function(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())if(!__lrxRawText.has(node))__lrxRawText.set(node,node.nodeValue||'');__lrxBaseApplyEnglishUI();const textWalker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(node=textWalker.nextNode()){const current=node.nodeValue||'',last=__lrxRenderedText.get(node);if(last!==undefined&&current!==last)__lrxRawText.set(node,current);const raw=__lrxRawText.get(node)||'',next=__lrxTranslateValue(raw);if(current!==next)node.nodeValue=next;__lrxRenderedText.set(node,next)}document.querySelectorAll('[aria-label],[title],[placeholder],[data-label]').forEach(el=>{let raw=__lrxRawAttrs.get(el);if(!raw){raw={};__lrxRawAttrs.set(el,raw)}let rendered=__lrxRenderedAttrs.get(el);if(!rendered){rendered={};__lrxRenderedAttrs.set(el,rendered)}for(const attr of ['aria-label','title','placeholder','data-label']){const current=el.getAttribute(attr);if(current===null)continue;if(rendered[attr]!==undefined&&current!==rendered[attr])raw[attr]=current;else if(raw[attr]===undefined)raw[attr]=current;const next=__lrxTranslateValue(raw[attr]);if(current!==next)el.setAttribute(attr,next);rendered[attr]=next}})};window.extendLRXEnglishDictionary=extra=>{Object.assign(UI_EN,extra||{});for(const [key,value] of Object.entries(extra||{})){try{const repaired=decodeURIComponent(escape(key));if(repaired!==key)UI_EN[repaired]=value}catch{}}__lrxBuildTranslationIndex();applyEnglishUI()};let __lrxTranslationTimer=0;const __lrxTranslationObserver=new MutationObserver(()=>{if(state.settings?.language!=='en')return;clearTimeout(__lrxTranslationTimer);__lrxTranslationTimer=setTimeout(()=>applyEnglishUI(),180)});__lrxTranslationObserver.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','placeholder','data-label']});function updateLanguageChip(){"
if "window.extendLRXEnglishDictionary" not in s:
    if needle not in s:
        raise SystemExit("Could not find language UI insertion point")
    s = s.replace(needle, bridge, 1)
    p.write_text(s)
PY
